function ExtractionListScreen() {
  const [extractions, setExtractions] = useState([]); const [loading, setLoading] = useState(true);
  const {isDark}=useTheme(); const theme=isDark?darkTheme:lightTheme;
  useEffect(()=>{fetchExtractions();},[]);
  const fetchExtractions=async()=>{try{const r=await axios.get(`${API_BASE_URL}/api/extractions?limit=50`);setExtractions(r.data);}catch(e){}finally{setLoading(false);}};
  if(loading)return<View style={[styles.container,{backgroundColor:theme.bg}]}><ActivityIndicator size="large" color="#1a237e" style={{marginTop:100}}/></View>;
  return(<ScrollView style={[styles.container,{backgroundColor:theme.bg}]}><View style={[styles.listHeader,{backgroundColor:theme.card}]}><Text style={[styles.sectionTitle,{color:theme.text}]}>📋 Archivio</Text></View>{extractions.map((ext,i)=>(<View key={i} style={[styles.extractionCard,{backgroundColor:theme.card}]}><Text style={[styles.extractionDate,{color:theme.text}]}>📅 {ext.extraction_date}</Text><Text style={[styles.extractionNumbers,{color:theme.inputText}]}>🎱 {ext.n1} - {ext.n2} - {ext.n3} - {ext.n4} - {ext.n5} - {ext.n6}</Text>{ext.jolly&&<Text style={styles.extractionExtra}>⭐ Jolly: {ext.jolly}</Text>}{ext.superstar&&<Text style={styles.extractionExtra}>🌟 SuperStar: {ext.superstar}</Text>}</View>))}</ScrollView>);
}
function AddExtractionScreen({navigation}) {
  const [date,setDate]=useState('');const [numbers,setNumbers]=useState(['','','','','','']);const [jolly,setJolly]=useState('');const [superstar,setSuperstar]=useState('');const [loading,setLoading]=useState(false);
  const {isDark}=useTheme();const theme=isDark?darkTheme:lightTheme;
  const handleSubmit=async()=>{if(!date||numbers.some(n=>!n||n<1||n>90)){Vibration.vibrate(200);Alert.alert('Errore','Inserisci data e 6 numeri validi');return;}if(jolly&&(jolly<1||jolly>90)){Alert.alert('Errore','Jolly 1-90');return;}if(superstar&&(superstar<1||superstar>90)){Alert.alert('Errore','SuperStar 1-90');return;}setLoading(true);try{await axios.post(`${API_BASE_URL}/api/extractions`,{date,numbers:numbers.map(Number),jolly:jolly?Number(jolly):null,superstar:superstar?Number(superstar):null});Vibration.vibrate([0,50,50,50,100]);Alert.alert('OK','Estrazione aggiunta!');navigation.goBack();}catch(e){Alert.alert('Errore');}finally{setLoading(false);}};
  return(<ScrollView style={[styles.container,{backgroundColor:theme.bg}]}><View style={[styles.formHeader,{backgroundColor:theme.card}]}><Text style={styles.formIcon}>➕</Text><Text style={[styles.sectionTitle,{color:theme.text}]}>Nuova Estrazione</Text></View><View style={[styles.formGroup,{backgroundColor:theme.card}]}><Text style={[styles.label,{color:theme.text}]}>📅 Data</Text><TextInput style={[styles.input,{backgroundColor:theme.input,color:theme.inputText}]} value={date} onChangeText={setDate} placeholder="AAAA-MM-GG" placeholderTextColor="#999"/></View><View style={[styles.formGroup,{backgroundColor:theme.card}]}><Text style={[styles.label,{color:theme.text}]}>🎱 6 Numeri</Text><View style={styles.numbersInputRow}>{numbers.map((n,i)=>(<TextInput key={i} style={[styles.numberInput,{backgroundColor:theme.input,color:theme.inputText}]} value={n} onChangeText={t=>{let m=[...numbers];m[i]=t;setNumbers(m);}} keyboardType="numeric" maxLength={2} placeholder={String(i+1)} placeholderTextColor="#999"/>))}</View></View><View style={[styles.formGroup,{backgroundColor:theme.card}]}><Text style={[styles.label,{color:theme.text}]}>⭐ Jolly (opzionale)</Text><TextInput style={[styles.input,{backgroundColor:theme.input,color:theme.inputText}]} value={jolly} onChangeText={setJolly} keyboardType="numeric" maxLength={2} placeholder="1-90" placeholderTextColor="#999"/></View><View style={[styles.formGroup,{backgroundColor:theme.card}]}><Text style={[styles.label,{color:theme.text}]}>🌟 SuperStar (opzionale)</Text><TextInput style={[styles.input,{backgroundColor:theme.input,color:theme.inputText}]} value={superstar} onChangeText={setSuperstar} keyboardType="numeric" maxLength={2} placeholder="1-90" placeholderTextColor="#999"/></View><TouchableOpacity style={styles.submitButton} onPress={handleSubmit} disabled={loading}><Text style={styles.buttonText}>{loading?'⏳ Salvataggio...':'💾 SALVA'}</Text></TouchableOpacity></ScrollView>);
}
function SubscriptionScreen() {
  const {isDark}=useTheme();const theme=isDark?darkTheme:lightTheme;
  return(<ScrollView style={[styles.container,{backgroundColor:theme.bg}]}><View style={[styles.subscriptionHeader,{backgroundColor:theme.header}]}><Text style={styles.subscriptionIcon}>💎</Text><Text style={styles.title}>Piani</Text><Text style={styles.subtitle}>✅ 3 giorni gratis</Text></View>{[{id:'weekly',name:'📅 Settimanale',price:'2.99',days:7,color:'#4caf50'},{id:'monthly',name:'📅 Mensile',price:'9.99',days:30,color:'#2196f3'},{id:'annual',name:'📅 Annuale',price:'79.99',days:365,color:'#9c27b0'}].map(p=>(<TouchableOpacity key={p.id} style={[styles.planCard,{borderLeftColor:p.color,backgroundColor:theme.card}]}><View style={styles.planInfo}><Text style={[styles.planName,{color:theme.text}]}>{p.name}</Text><Text style={[styles.planDuration,{color:theme.subtext}]}>⏱️ {p.days}gg</Text></View><Text style={[styles.planPrice,{color:p.color}]}>€{p.price}</Text></TouchableOpacity>))}</ScrollView>);
}

// MAIN APP
export default function App() {
  const colorScheme=useColorScheme();const [isDark,setIsDark]=useState(colorScheme==='dark');
  return(<ThemeContext.Provider value={{isDark,setIsDark}}><NavigationContainer><Stack.Navigator screenOptions={{headerStyle:{backgroundColor:isDark?'#000':'#1a237e'},headerTintColor:'#fff'}}><Stack.Screen name="Splash" component={SplashScreen} options={{headerShown:false}}/><Stack.Screen name="Terms" component={TermsScreen} options={{headerShown:false}}/><Stack.Screen name="Login" component={LoginScreen} options={{headerShown:false}}/><Stack.Screen name="Register" component={RegisterScreen} options={{title:'📝 Registrazione'}}/><Stack.Screen name="Home" component={HomeScreen} options={{title:'🏠 Home',headerLeft:()=>null}}/><Stack.Screen name="Analysis" component={AnalysisScreen} options={{title:'🔮 Analisi'}}/><Stack.Screen name="Results" component={ResultsScreen} options={{title:'🏆 Risultati'}}/><Stack.Screen name="Generator" component={GeneratorScreen} options={{title:'🎲 Generatore'}}/><Stack.Screen name="Check" component={CheckScreen} options={{title:'✅ Verifica Giocata'}}/><Stack.Screen name="NumberMeaning" component={NumberMeaningScreen} options={{title:'🔢 Significato Numeri'}}/><Stack.Screen name="ExtractionList" component={ExtractionListScreen} options={{title:'📋 Archivio'}}/><Stack.Screen name="AddExtraction" component={AddExtractionScreen} options={{title:'➕ Nuova'}}/><Stack.Screen name="Subscription" component={SubscriptionScreen} options={{title:'💎 Abbonamento'}}/></Stack.Navigator></NavigationContainer></ThemeContext.Provider>);
}

